    private void jButton1MouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_jButton1MouseClicked
        // TODO add your handling code here:
        float n1= Float.parseFloat(tf1.getText());
        float n2= Float.parseFloat(tf2.getText());
        int t= Integer.parseInt(tf8.getText());
        int a= Integer.parseInt(tf3.getText());
        int b= Integer.parseInt(tf4.getText());
        int c= Integer.parseInt(tf5.getText());
        int d= Integer.parseInt(tf6.getText());
        int e= Integer.parseInt(tf7.getText());
        int n3 = tf10.getText().trim().isEmpty() ? 0 : Integer.parseInt(tf10.getText());
        float f=(a+b+c+d+e)/5;
        n1= n1+(f*t);
        n2=n2+(f*t)-n3;
        float rrs = (n2/n1)*100;
        lb3.setText(""+rrs+" %");
        
        
        
    }//GEN-LAST:event_jButton1MouseClicked

